  assert.equal(fs.realpathSync(NODE), NODE);
  const m = metadata(NODE);
  assert.equal(m.type, 'file'); assert.equal(m.mode, 0o755);
  for (const k of ['device', 'inode', 'uid', 'gid', 'mtimeNs', 'ctimeNs'])
